function downloadImportWarnings(){if(!xmlPreview?.warnings.length)return;let rows=[['Successor task','Subcontractor','Predecessor reference','Source project/file','Review reason'],...xmlPreview.warnings.map(w=>{let successor=xmlPreview.records.find(t=>t.source_uid===w.successor_source_uid);return [successor?.title||'Not imported',successor?.subcontractor_name||'',w.predecessor_source_uid||'',w.source_name||'',w.reason]})];let csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='siteplan-unresolved-links.csv';a.click();URL.revokeObjectURL(a.href)}
function renderImportPage(box){let p=xmlPreview;box.innerHTML=`<h1>Import a Microsoft Project schedule</h1>${importStorageReady?'':`<div class="migration-note"><b>One-time setup needed before saving.</b><span>Run <strong>supabase/import-schedule.sql</strong> in your Supabase SQL Editor. The app can still preview the file before you do this.</span></div>`}<p class="linknote import-intro">Choose the combined Master Project XML export. SitePlan will preview subcontractors, tasks and verified Finish-to-Start links before saving anything.</p><div class="import-card"><label class="file-label">Select the Master Project XML<input type="file" accept=".xml,text/xml,application/xml" onchange="importFileChanged(this)"></label><p class="import-help">The import skips summary headings, blank rows and “&lt;New Task&gt;” placeholders. External predecessor references are kept for review; they are never imported as work.</p></div>${p?`<div class="import-summary"><div><b>${p.subcontractors.length}</b><span>Subcontractors</span></div><div><b>${p.records.length}</b><span>Tasks</span></div><div><b>${p.edges.length}</b><span>Verified links</span></div><div class="${p.warnings.length?'warn':''}"><b>${p.warnings.length}</b><span>Links / rows to review</span></div></div><h2>Subcontractor preview</h2><div class="import-company-list">${p.subcontractors.map(n=>`<span>${esc(n)} <small>${p.records.filter(t=>t.subcontractor_name===n).length} items</small></span>`).join('')}</div><div class="import-details"><b>${esc(p.fileName)}</b><span>${p.skippedBlank} blank rows and ${p.skippedPlaceholder} placeholders skipped${p.fractional?`; ${p.fractional} fractional-day durations rounded up to whole working days`:''}.</span><span>Existing tasks imported from this same XML are updated by their Project UID. Manually added work is left in place.</span></div>${p.warnings.length?`<h2 class="warning-heading">Review these references before relying on the sequence <span class="count-pill">${p.warnings.length}</span></h2><p class="linknote">These will be saved as review warnings. They won’t become tasks or move dates. Download the list if you want to work through them separately.</p><div class="warning-list">${p.warnings.slice(0,12).map(w=>{let t=p.records.find(x=>x.source_uid===w.successor_source_uid);return `<div class="warning-row"><b>${esc(t?.title||'Row not imported')}</b><span>${esc(w.reason)}</span><small>${esc(t?.subcontractor_name||'')} · predecessor ${esc(w.predecessor_source_uid||'unknown')}${w.source_name?' · '+esc(w.source_name):''}</small></div>`}).join('')}${p.warnings.length>12?`<div class="import-help">Showing 12 of ${p.warnings.length}; download the full list.</div>`:''}</div><button class="btn" onclick="downloadImportWarnings()">Download review list (CSV)</button>`:'<div class="success-box">All predecessor links in this file can be matched to imported tasks.</div>'}<div class="import-actions"><button class="btn" onclick="clearImportPreview()">Clear preview</button><button class="btn primary" onclick="commitXmlImport()" ${p.records.length&&importStorageReady?'':'disabled'}>Import ${p.records.length} tasks</button></div>`:'<div class="import-empty">No file selected. Choose the combined Master Project XML to see a review preview.</div>'}`}
