function toggleOriginalDetails(){let block=$('#originalDetailsFields'),flag=document.querySelector('[name="edit_original_details"]'),button=document.querySelector('.edit-original-toggle');if(!block||!flag)return;let show=block.classList.contains('hidden');block.classList.toggle('hidden',!show);flag.value=show?'true':'false';block.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=!show);button.textContent=show?'Close original details':'Edit original details'}
